for path,entries in groups.items():
 raw=(root/path).read_bytes(); src=raw.decode('utf8').splitlines(); digest=hashlib.sha256(raw).hexdigest(); name=path.replace('/','_')+'.md'; out=['# شرح `'+path+'`','',f'بصمة المصدر SHA-256: `{digest}`.','','المقاطع من المصدر؛ النصوص الطويلة المقتبسة في قوالب التقرير تؤدي وظيفة توثيق النتائج المحفوظة ولا تنفذ تجارب.','']
 for start,end,desc in entries: out += [f'## الأسطر {start}–{end}','','```python',*src[start-1:end],'```','',desc,'']
 (base/'line_by_line'/name).write_text('\n'.join(out),encoding='utf8')
 manifest[path]={'document':'line_by_line/'+name,'ranges':[[a,b] for a,b,_ in entries],'sha256':digest,'review':'مراجعة يدوية غير مستقلة','quote_verification':'آلي'}
(base/'validation_report_manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2),encoding='utf8')
